#include <cstdio>
#include <cstring>
#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n, ans = 0, cnt[26] = {};
    string s;

    scanf("%d", &n);
    cin >> s;

    for (char c : s) {
        if (c >= 'A' && c <= 'Z') {
            int total = 0;
            for (int x : cnt) total += (x != 0);
            ans = max(ans, total);
            memset(cnt, 0, sizeof(cnt));
        } else {
            cnt[c - 'a'] = 1;
        }
    }

    int total = 0;
    for (int x : cnt) total += (x != 0);
    ans = max(ans, total);

    printf("%d\n", ans);
    return 0;
}

